package main
import("encoding/json";"net/http";"net/http/httptest";"os";"regexp";"strconv";"strings";"wormhole-reference/db";"github.com/jackc/pgx/v5";"github.com/jackc/pgx/v5/stdlib")
type Server struct{database *db.DB}
func(s *Server)pg(http.ResponseWriter)*db.DB{return s.database}
func pathInt(r *http.Request,k string)(int64,bool){n,e:=strconv.ParseInt(r.PathValue(k),10,64);return n,e==nil}
func decode(r *http.Request,v any)error{return json.NewDecoder(r.Body).Decode(v)}
func writeJSON(w http.ResponseWriter,s int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(s);if e:=json.NewEncoder(w).Encode(v);e!=nil{panic(e)}}
func writeErr(w http.ResponseWriter,s int,m string){writeJSON(w,s,map[string]any{"error":m})}
func check(e error){if e!=nil{panic(e)}}
func main(){schema:=os.Getenv("WORMHOLE_RULE_SCHEMA");if !regexp.MustCompile("^codex_rule_ref_[0-9_]+$").MatchString(schema){panic("bad isolated schema")};cfg,e:=pgx.ParseConfig(os.Getenv("WORMHOLE_RULE_DSN"));check(e);cfg.RuntimeParams["search_path"]=schema;sql:=stdlib.OpenDB(*cfg);defer sql.Close();raw,e:=os.ReadFile("db/schema.sql");check(e);_,e=sql.Exec(string(raw));check(e)
 var input struct{SQL string;Checks []struct{TaskID int64;IDs []int64};Cases []struct{Method,Path string;Body any}};check(json.NewDecoder(os.Stdin).Decode(&input));_,e=sql.Exec(input.SQL);check(e);s:=&Server{database:&db.DB{DB:sql}};mux:=http.NewServeMux()
 mux.HandleFunc("GET /api/asset-intercept/rules",s.assetInterceptListRules);mux.HandleFunc("POST /api/asset-intercept/rules",s.assetInterceptCreateRule);mux.HandleFunc("PUT /api/asset-intercept/rules/{id}",s.assetInterceptUpdateRule);mux.HandleFunc("DELETE /api/asset-intercept/rules/{id}",s.assetInterceptDeleteRule);mux.HandleFunc("POST /api/asset-intercept/rules/{id}/toggle",s.assetInterceptToggleRule)
 mux.HandleFunc("GET /api/tasks/{id}/intercept-rules",s.taskInterceptListRules);mux.HandleFunc("POST /api/tasks/{id}/intercept-rules",s.taskInterceptCreateRule);mux.HandleFunc("PUT /api/tasks/{id}/intercept-rules/{rid}",s.taskInterceptUpdateRule);mux.HandleFunc("DELETE /api/tasks/{id}/intercept-rules/{rid}",s.taskInterceptDeleteRule);mux.HandleFunc("POST /api/tasks/{id}/intercept-rules/{rid}/toggle",s.taskInterceptToggleRule)
 out:=[]any{};for _,c:=range input.Cases{body:="";if c.Body!=nil{b,e:=json.Marshal(c.Body);check(e);body=string(b)};r:=httptest.NewRequest(c.Method,c.Path,strings.NewReader(body));w:=httptest.NewRecorder();mux.ServeHTTP(w,r);var j any;check(json.Unmarshal(w.Body.Bytes(),&j));out=append(out,map[string]any{"status":w.Code,"json":j})};checks:=[]any{};for _,c:=range input.Checks{hits,e:=s.database.Assets().CheckAssetsIntercept(c.TaskID,c.IDs);check(e);values:=[]any{};for _,h:=range hits{values=append(values,map[string]any{"asset_id":h.Asset.ID,"reason":h.Reason,"description":h.Describe()})};checks=append(checks,values)};check(json.NewEncoder(os.Stdout).Encode(map[string]any{"responses":out,"checks":checks}))}
